<?php
$filter=isset($_GET['module'])?$module:null;if($user['role']==='librarian')$filter='library';if($user['role']==='president')$filter='substitution';if($user['role']==='student'){echo '<p><a class="button" href="?page=research">Open Research Management</a></p>';return;}
$showDeleted=$user['role']==='admin'&&($_GET['show_deleted']??'')==='1';
$where=" WHERE r.status".($showDeleted?"='Deleted'":"<>'Deleted'").($filter?' AND r.module=?':'');$args=$filter?[$filter]:[];
$count=(int)q('SELECT COUNT(*) FROM requests r'.$where,$args)->fetchColumn();
$pages=max(1,(int)ceil($count/10));$number=min($pages,max(1,(int)($_GET['p']??1)));$offset=($number-1)*10;
$recent=all('SELECT r.id,r.module,r.status,r.created_at,r.payload,r.applicant_id,r.department,u.name FROM requests r JOIN users u ON u.id=r.applicant_id'.$where.' ORDER BY r.id DESC LIMIT 10 OFFSET '.$offset,$args);
?>
<div class="heading"><div><span class="eyebrow">ACADEMIC SERVICES</span><h1><?= $filter?e(modules()[$filter]).' Records':'Academic Services'?></h1></div></div>
<div class="service-links"><?php foreach(navigationModules($user)as $key=>$label):?><a class="button service-tile service-<?=$key?>" href="?page=<?=$key==='exam'?'exam_portal':'new'?>&module=<?=$key?>"><?=e($key==='exam'?'Exam Cell Portal':$label)?> ＋</a><?php endforeach;?></div>
<?php if(in_array($user['role'],['hod','daa','president'],true)):?><p><a class="button" href="?page=reports&amp;module=substitution">View substitution requests and approvals</a></p><?php endif;?>
<?php if($user['role']==='admin'):?><p><a href="?show_deleted=<?=$showDeleted?'0':'1'?>"><?=$showDeleted?'Back to active records':'View deleted requests (audit)'?></a></p><?php endif;?>
<section class="card"><div class="table-wrap"><table><thead><tr><th>Sl. No.</th><th>Service</th><th>Name</th><th>Department</th><th>Date</th><th>Status</th></tr></thead><tbody>
<?php foreach($recent as $rowIndex=>$r):$data=json_decode($r['payload'],true);?><tr><td><?=$offset+$rowIndex+1?></td><td><span class="service-label service-<?=e($r['module'])?>"><?=e(modules()[$r['module']])?></span></td><td><?= $r['module']==='consultation'?'Student consultation':e($data['applicant_name']??$r['name'])?></td><td><?=e($r['department'])?></td><td><?php if($r['module']==='substitution'):?><?=e($data['travel_start']??'—')?><small>to <?=e($data['travel_end']??'—')?></small><?php else:?><?=e($data['booking_date']??substr($r['created_at'],0,10))?><?php endif;?></td><td><span class="badge <?=in_array($r['status'],['Approved','Historical Approved','Completed','Confirmed'])?'good':(str_contains($r['status'],'Rejected')?'bad':'')?>"><?=e(requestStatusLabel($r['status']))?></span><?php if(canView($user,$r)):?><small><a href="?page=detail&amp;module=<?=e($r['module'])?>&amp;id=<?=$r['id']?>"><?=($r['module']==='substitution'&&substitutionActions($user,$r))?'Review / approve':'View request'?></a></small><?php endif;?></td></tr><?php endforeach;?>
<?php if(!$recent):?><tr><td colspan="6" class="empty">No services submitted yet.</td></tr><?php endif;?></tbody></table></div>
<div class="pagination"><small><?=$count?> records · Page <?=$number?> of <?=$pages?></small><div><?php if($number>1):?><a class="button secondary" href="?<?=e(http_build_query(array_filter(['module'=>$filter,'p'=>$number-1,'show_deleted'=>$showDeleted?'1':null],fn($v)=>$v!==null)))?>">Previous</a><?php endif;?> <?php if($number<$pages):?><a class="button secondary" href="?<?=e(http_build_query(array_filter(['module'=>$filter,'p'=>$number+1,'show_deleted'=>$showDeleted?'1':null],fn($v)=>$v!==null)))?>">Next</a><?php endif;?></div></div></section>
